using EduCenterManagement.Models; using EduCenterManagement.Repositories; using EduCenterManagement.ViewModels.Common; using EduCenterManagement.ViewModels.Notification;
namespace EduCenterManagement.Services;
public sealed class NotificationService(INotificationRepository repository):INotificationService { static string Clip(string x,int n)=>x.Length<=n?x:x[..n]; public Task CreateAsync(int userId,string type,string title,string message,string? rt=null,int? ri=null,int? studentId=null,CancellationToken ct=default)=>repository.AddAsync(new Notification{UserId=userId,Type=Clip(type,50),Title=Clip(title,200),Message=Clip(message,1000),ReferenceType=rt is null?null:Clip(rt,50),ReferenceId=ri,StudentId=studentId},ct); public async Task CreateForParentsOfStudentAsync(int id,string type,string title,string message,string? rt=null,int? ri=null,CancellationToken ct=default){foreach(var uid in await repository.GetAcceptedParentUserIdsAsync(id,ct))await CreateAsync(uid,type,title,message,rt,ri,id,ct);} public Task<int> GetUnreadCountAsync(int u,CancellationToken ct=default)=>repository.GetUnreadCountAsync(u,ct);public Task<PagedResult<NotificationItemViewModel>> GetListAsync(int u,bool unread,int? s,int p,int ps,CancellationToken ct=default)=>repository.GetListAsync(u,unread,s,p,ps,ct);public Task MarkAsReadAsync(int u,int n,CancellationToken ct=default)=>repository.MarkAsReadAsync(u,n,ct);public Task MarkAllAsReadAsync(int u,CancellationToken ct=default)=>repository.MarkAllAsReadAsync(u,ct); }
